# ── bookkeeping kit: shared helpers (inlined into each node by gen-ext.js) ──
import json
import re
import datetime
from zoneinfo import ZoneInfo

# Knowledge layout. Folders may nest at most 2 levels, so inbox folders are top-level.
BK_SETTINGS = "Bookkeeping/settings.json"
BK_CLIENTS = "Bookkeeping/Clients"
BK_RULES = "Bookkeeping/Rules"
BK_BILLS = "Bookkeeping/Bills"
BK_INBOX = "Bookkeeping Inbox"
BK_PROCESSED = "Bookkeeping Processed"
BK_FAILED = "Bookkeeping Failed"
BK_MAIL = "Bookkeeping/Mail"
BK_REQUESTS = "Bookkeeping Requests"


def bk_money(value):
    """Parse 1234.5, "1,234.50", "$12" or "A$ 12.00" into a float; None when blank or not a number."""
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    s = re.sub(r"[^0-9.\-]", "", str(value))
    if s in ("", "-", ".", "-."):
        return None
    try:
        return float(s)
    except ValueError:
        return None


def bk_tz(settings):
    # The sandbox may lack the tz database; fall back to AEST (UTC+10) rather than failing the run.
    try:
        return ZoneInfo((settings or {}).get("timezone") or "Australia/Sydney")
    except Exception:
        return datetime.timezone(datetime.timedelta(hours=10))


def bk_today(settings):
    return datetime.datetime.now(bk_tz(settings)).date()


def bk_norm(name):
    s = re.sub(r"[^a-z0-9 ]+", " ", str(name or "").lower())
    s = re.sub(r"\b(pty|ltd|limited|p/l|the|inc|co)\b", " ", s)
    return re.sub(r"\s+", " ", s).strip()


# ── bookkeeping kit: Xero ledger adapter (inlined into Xero nodes by gen-ext.js) ──
# Every write passes xero_tenant_id so it lands in the client's own Xero organisation
# (myhub-mcp-servers PR #558). Reads pass it too.
import base64
from collections import Counter

XERO = "xero-accounting"
XERO_EXPENSE_TYPES = {"EXPENSE", "DIRECTCOSTS", "OVERHEADS", "FIXED", "CURRENT", "INVENTORY", "PREPAYMENT", "NONCURRENT"}
XERO_REVENUE_TYPES = {"REVENUE", "SALES", "OTHERINCOME"}
XERO_DEAD = {"DELETED", "VOIDED"}


def xero_call(tool, tenant_id=None, **args):
    if tenant_id:
        args["xero_tenant_id"] = tenant_id
    # Bound first on purpose: the platform's Publish lint only counts plain assignments as a function's own names,
    # so an `except ... as exc` name alone reads as undefined inside a helper.
    exc = None
    try:
        return api.connectors.invoke(server=XERO, tool=tool, args=args)
    except Exception as exc:
        raise RuntimeError(xero_error_text(exc)) from None


def xero_error_text(exc):
    """Xero's own validation messages (the useful part, at the end of a long error), else the error text."""
    text = str(exc)
    at = text.find("ValidationErrors")
    messages = []
    for m in re.findall(r'"Message"\s*:\s*"((?:[^"\\]|\\.)*)"', text[at:] if at >= 0 else ""):
        if m not in messages:
            messages.append(m)
    return ("Xero says: " + "; ".join(messages)) if messages else text[:600]


def xero_q(value):
    return str(value).replace("\\", "\\\\").replace('"', '\\"')


def xero_rows(result, key):
    if isinstance(result, dict):
        return result.get(key) or []
    if isinstance(result, list):
        return result
    return []


def xero_find_supplier(tenant_id, name, abn):
    """Existing contact by ABN (TaxNumber) first, then by normalised name. None when not found."""
    if not name:
        return None
    rows = xero_rows(xero_call("list_contacts", tenant_id, searchTerm=str(name)[:60]), "Contacts")
    abn_digits = "".join(ch for ch in str(abn or "") if ch.isdigit())
    if abn_digits:
        for c in rows:
            if "".join(ch for ch in str(c.get("TaxNumber") or "") if ch.isdigit()) == abn_digits:
                return c
    target = bk_norm(name)
    for c in rows:
        if bk_norm(c.get("Name")) == target:
            return c
    return None


def xero_history_coding(tenant_id, contact_id, doc_type="ACCPAY"):
    """Most common (AccountCode, TaxType) on the contact's recent bills (or sales invoices), or None."""
    if not contact_id:
        return None
    where = 'Type=="%s" AND Contact.ContactID==guid("%s")' % (doc_type, xero_q(contact_id))
    rows = xero_rows(xero_call("list_invoices", tenant_id, where=where, order="Date DESC", page=1), "Invoices")
    pairs = []
    for inv in rows[:5]:
        if inv.get("Status") in XERO_DEAD:
            continue
        for li in inv.get("LineItems") or []:
            if li.get("AccountCode"):
                pairs.append((li.get("AccountCode"), li.get("TaxType") or ""))
    if not pairs:
        return None
    (code, tax), _ = Counter(pairs).most_common(1)[0]
    return {"account_code": code, "tax_type": tax}


def xero_chart(tenant_id, doc_type="ACCPAY"):
    """Active accounts and tax rates a bill (expense side) or a sales invoice (revenue side) can use."""
    sales = doc_type == "ACCREC"
    accounts = xero_rows(xero_call("list_accounts", tenant_id, where='Status=="ACTIVE"'), "Accounts")
    taxes = xero_rows(xero_call("list_tax_rates", tenant_id), "TaxRates")
    kinds = XERO_REVENUE_TYPES if sales else XERO_EXPENSE_TYPES
    acc = [{"code": a.get("Code"), "name": a.get("Name"), "type": a.get("Type"),
            "description": (a.get("Description") or "")[:120]}
           for a in accounts if a.get("Code") and a.get("Type") in kinds]
    tax = [{"type": t.get("TaxType"), "name": t.get("Name"), "rate": t.get("EffectiveRate")}
           for t in taxes if t.get("Status", "ACTIVE") == "ACTIVE"
           and t.get("CanApplyToRevenue" if sales else "CanApplyToExpenses", True)]
    return acc, tax


def xero_bill_body(proposal, status):
    lines = []
    for ln in proposal.get("lines") or []:
        qty = ln.get("quantity") or 1
        unit = ln.get("unit_amount")
        if unit is None:
            unit = round((ln.get("line_amount") or 0) / qty, 4) if qty else (ln.get("line_amount") or 0)
        item = {"Description": (ln.get("description") or "")[:4000], "Quantity": qty, "UnitAmount": unit}
        if ln.get("item_code"):
            item["ItemCode"] = ln["item_code"]
        if ln.get("account_code"):
            item["AccountCode"] = ln["account_code"]
        if ln.get("tax_type"):
            item["TaxType"] = ln["tax_type"]
        lines.append(item)
    body = {
        "Type": proposal.get("doc_type") or "ACCPAY",
        "Contact": {"ContactID": proposal["contact"]["id"]},
        "Date": proposal.get("date"),
        "LineAmountTypes": proposal.get("line_amount_types") or "Exclusive",
        "LineItems": lines,
        "Status": status,
    }
    for key, field in (("due_date", "DueDate"), ("invoice_number", "InvoiceNumber"),
                       ("reference", "Reference"), ("currency", "CurrencyCode")):
        if proposal.get(key):
            body[field] = proposal[key]
    return body


def xero_ensure_contact(tenant_id, proposal):
    contact = proposal.get("contact") or {}
    if contact.get("id"):
        return contact["id"]
    # An earlier attempt may have created the contact before Xero rejected the bill; reuse it.
    found = xero_find_supplier(tenant_id, contact.get("name"), contact.get("abn"))
    if found and found.get("ContactID"):
        proposal["contact"]["id"] = found["ContactID"]
        proposal["contact"]["is_new"] = False
        return found["ContactID"]
    body = {"Name": contact.get("name") or "Unknown supplier"}
    if contact.get("abn"):
        body["TaxNumber"] = contact["abn"]
    if contact.get("email"):
        body["EmailAddress"] = contact["email"]
    rows = xero_rows(xero_call("create_contact", tenant_id, contact=body), "Contacts")
    if not rows or not rows[0].get("ContactID"):
        raise RuntimeError("Xero did not return the new contact")
    proposal["contact"]["id"] = rows[0]["ContactID"]
    proposal["contact"]["is_new"] = False
    return rows[0]["ContactID"]


def xero_terms_due(terms, issue):
    """Due date from Xero payment terms ({"Day": n, "Type": ...}) for a bill dated `issue`, or None."""
    try:
        day = int(str((terms or {}).get("Day") or ""))
    except (TypeError, ValueError):
        return None
    kind = str((terms or {}).get("Type") or "")
    next_month = (issue.replace(day=1) + datetime.timedelta(days=32)).replace(day=1)
    if kind == "DAYSAFTERBILLDATE":
        return issue + datetime.timedelta(days=day)
    if kind == "DAYSAFTERBILLMONTH":
        return next_month - datetime.timedelta(days=1) + datetime.timedelta(days=day)
    if kind == "OFCURRENTMONTH":
        return issue.replace(day=min(max(day, 1), (next_month - datetime.timedelta(days=1)).day))
    if kind == "OFFOLLOWINGMONTH":
        after = (next_month + datetime.timedelta(days=32)).replace(day=1)
        return next_month.replace(day=min(max(day, 1), (after - datetime.timedelta(days=1)).day))
    return None


def xero_default_due(tenant_id, contact, issue_date, doc_type="ACCPAY"):
    """(due date, where it came from) for a bill or invoice with no due date: the contact's payment terms in Xero,
    then the organisation's default terms, then the document date. ("", "") when there's no usable date."""
    side = "Sales" if doc_type == "ACCREC" else "Bills"
    who = "customer" if doc_type == "ACCREC" else "supplier"
    try:
        issue = datetime.date.fromisoformat(str(issue_date or "")[:10])
    except ValueError:
        return "", ""
    due = xero_terms_due(((contact or {}).get("PaymentTerms") or {}).get(side), issue)
    if due:
        return str(due), "the " + who + "'s payment terms in Xero"
    try:
        org = xero_call("get_organisation", tenant_id)
        if isinstance(org, dict) and isinstance(org.get("Organisations"), list):
            org = org["Organisations"][0] if org["Organisations"] else {}
        elif isinstance(org, list):
            org = org[0] if org else {}
        due = xero_terms_due(((org or {}).get("PaymentTerms") or {}).get(side), issue)
    except Exception:
        due = None
    if due:
        return str(due), "the organisation's default " + ("invoice" if side == "Sales" else "bill") + " terms in Xero"
    return str(issue), "the invoice date, because no payment terms are set in Xero"


def xero_create_bill(tenant_id, proposal, status="DRAFT"):
    xero_ensure_contact(tenant_id, proposal)
    rows = xero_rows(xero_call("create_invoice", tenant_id, invoice=xero_bill_body(proposal, status)), "Invoices")
    if not rows or not rows[0].get("InvoiceID"):
        raise RuntimeError("Xero did not return the new bill")
    if not proposal.get("invoice_number") and rows[0].get("InvoiceNumber"):
        # A raised invoice takes the organisation's next number.
        proposal["invoice_number"] = rows[0]["InvoiceNumber"]
    return rows[0]["InvoiceID"]


def xero_items(tenant_id):
    """The organisation's sold items: [{code, name, description, price, account_code, tax_type}]."""
    out = []
    for it in xero_rows(xero_call("list_items", tenant_id), "Items"):
        if it.get("IsSold") is False or not it.get("Code"):
            continue
        sd = it.get("SalesDetails") or {}
        out.append({"code": str(it["Code"]), "name": str(it.get("Name") or ""), "description": str(it.get("Description") or "")[:200],
                    "price": bk_money(sd.get("UnitPrice")), "account_code": str(sd.get("AccountCode") or ""),
                    "tax_type": str(sd.get("TaxType") or "")})
    return out


# ── Draft the invoice ──


REQUEST_PROMPT = (
    "A small business has asked its bookkeeper to raise a sales invoice to one of its customers. From the request, "
    "extract the invoice to raise. Never guess: a quantity, price, date or email the request doesn't state is null. "
    "'items' lists the business's Xero items; when a line is one of them, give its code in item_code. A price the "
    "request states wins over the item's price. Dates as YYYY-MM-DD (Australian requests are day/month/year). If the "
    "request isn't actually asking for an invoice to be raised, set is_request false."
)
REQUEST_HINT = ('{"is_request": true, "customer_name": "", "customer_email": null, "reference": "", "invoice_date": null, '
                '"due_date": null, "lines": [{"description": "", "quantity": 1, "unit_amount": null, "item_code": null}], '
                '"notes": ""}')
SALES_CODE_PROMPT = (
    "You code sales invoice lines for an Australian bookkeeper: the client is invoicing its customer. For each line, "
    "pick the best revenue account code from 'accounts' and the tax type from 'tax_rates' (GST on income for taxable "
    "sales when the business is GST registered, GST-free income or BAS-excluded otherwise). Use the client's coding "
    "notes when they apply. Only use codes that appear in the lists. Give a one-sentence reason and a confidence of "
    "high, medium or low for each line."
)
CODE_HINT = '[{"index": 0, "account_code": "200", "tax_type": "OUTPUT", "reason": "", "confidence": "high"}]'

problem = params.get("problem") or ""
ctx = params.get("ctx") or {}
request = params.get("request") or {}
proposal = {}
warnings = []
blocking = []
bill_id = ""

if not problem:
    try:
        settings = ctx.get("settings") or {}
        client = ctx.get("client") or {}
        tenant = client["xero_tenant_id"]
        items = xero_items(tenant)
        asked = api.ai.extract(
            prompt=REQUEST_PROMPT,
            input=json.dumps({"business": client.get("name"), "today": str(bk_today(settings)),
                              "request": {"from": request.get("from"), "subject": request.get("subject"),
                                          "text": str(request.get("text") or "")[:8000]},
                              "items": [{"code": i["code"], "name": i["name"], "description": i["description"],
                                         "price": i["price"]} for i in items[:200]]})[:30000],
            schema_hint=REQUEST_HINT,
        )
        asked = asked if isinstance(asked, dict) else {}
        customer = str(asked.get("customer_name") or "").strip()
        if not asked:
            problem = "The AI couldn't read this request."
        elif asked.get("is_request") is False:
            problem = "This doesn't look like a request to raise an invoice, so nothing was drafted."
        elif not customer:
            problem = "The request doesn't say which customer to invoice."
        elif not (asked.get("lines") or []):
            problem = "The request doesn't say what to invoice."
    except Exception as exc:
        problem = "Couldn't read the request: " + str(exc)[:400]
        asked, customer, items, client, settings, tenant = {}, "", [], {}, {}, ""

if not problem:
    try:
        contact = xero_find_supplier(tenant, customer, "")
        email = str((contact or {}).get("EmailAddress") or asked.get("customer_email") or "").strip()
        if not contact:
            warnings.append("New customer: \"" + customer + "\" isn't in Xero yet. The contact is created when you approve"
                            + (" (with " + email + ")." if email else "."))
        if not email:
            warnings.append("There's no email address for " + customer + ", so Xero can't email the invoice. Add one to "
                            "the contact in Xero, or send the invoice yourself.")

        accounts, taxes = xero_chart(tenant, "ACCREC")
        codes = {a["code"] for a in accounts}
        tax_types = {t["type"] for t in taxes}
        rates = {t["type"]: bk_money(t.get("rate")) or 0 for t in taxes}
        by_code = {i["code"].lower(): i for i in items}
        rules = (ctx.get("rules") or {}).get("customers") or {}
        rule = (rules.get(contact.get("ContactID")) if contact else None) or rules.get("name:" + bk_norm(customer))
        hist = xero_history_coding(tenant, contact.get("ContactID"), "ACCREC") if contact else None

        lines = []
        for i, ln in enumerate(asked.get("lines") or []):
            ln = ln if isinstance(ln, dict) else {}
            item = by_code.get(str(ln.get("item_code") or "").lower())
            qty = bk_money(ln.get("quantity")) or 1
            unit = bk_money(ln.get("unit_amount"))
            line = {"description": str(ln.get("description") or (item or {}).get("name") or "")[:400], "quantity": qty,
                    "item_code": (item or {}).get("code") or "", "price_source": "request" if unit is not None else ""}
            if unit is None and item and item.get("price") is not None:
                unit = item["price"]
                line["price_source"] = "the Xero item " + item["code"]
            line["unit_amount"] = unit
            line["line_amount"] = round(qty * unit, 2) if unit is not None else None
            if item and item.get("account_code"):
                line.update(account_code=item["account_code"], tax_type=item.get("tax_type") or "", source="item",
                            reason="From the Xero item " + item["code"], confidence="high")
            elif rule and rule.get("account_code"):
                line.update(account_code=rule["account_code"], tax_type=rule.get("tax_type") or "", source="rule",
                            reason="Coding rule saved for this customer", confidence="high")
            elif hist:
                line.update(account_code=hist["account_code"], tax_type=hist["tax_type"], source="history",
                            reason="Same coding as this customer's recent invoices", confidence="high")
            lines.append(line)

        uncoded = [i for i, l in enumerate(lines) if not l.get("account_code")]
        if uncoded:
            coded = api.ai.extract(
                prompt=SALES_CODE_PROMPT,
                input=json.dumps({"customer": customer, "gst_registered": bool(client.get("gst_registered")),
                                  "client_notes": client.get("notes") or "",
                                  "lines": [{"index": i, "description": lines[i]["description"], "amount": lines[i]["line_amount"]}
                                            for i in uncoded],
                                  "accounts": accounts[:300], "tax_rates": taxes})[:30000],
                schema_hint=CODE_HINT,
            )
            for c in coded if isinstance(coded, list) else []:
                if isinstance(c, dict) and isinstance(c.get("index"), (int, float)) and int(c["index"]) in uncoded:
                    lines[int(c["index"])].update(account_code=str(c.get("account_code") or ""), tax_type=str(c.get("tax_type") or ""),
                                                  source="ai", reason=str(c.get("reason") or "Suggested by AI"),
                                                  confidence=str(c.get("confidence") or "low").lower())

        for i, l in enumerate(lines):
            if l.get("account_code") and l["account_code"] not in codes:
                warnings.append("Line " + str(i + 1) + ": account " + l["account_code"] + " isn't an active revenue account in Xero.")
                l["account_code"] = ""
            if l.get("tax_type") and l["tax_type"] not in tax_types:
                l["tax_type"] = ""
            if not l.get("account_code"):
                l["confidence"] = "low"
                blocking.append("Line " + str(i + 1) + " has no account code. Add one in your changes.")
            if l["line_amount"] is None:
                l["confidence"] = "low"
                blocking.append("Line " + str(i + 1) + " (" + l["description"][:60] + ") has no price. Add it in your "
                                "changes, e.g. \"line " + str(i + 1) + " unit price 180\".")
            elif l.get("price_source") and l["price_source"] != "request":
                l["reason"] = str(l.get("reason") or "") + ". Price from " + l["price_source"]

        priced = [l for l in lines if l["line_amount"] is not None]
        subtotal = round(sum(l["line_amount"] for l in priced), 2)
        tax = round(sum(l["line_amount"] * rates.get(l.get("tax_type") or "", 0) / 100 for l in priced), 2)
        date = str(asked.get("invoice_date") or bk_today(settings))[:10]
        due = str(asked.get("due_date") or "")[:10]
        if not due:
            due, came_from = xero_default_due(tenant, contact, date, "ACCREC")
            if due:
                warnings.append("Due " + due + ", from " + came_from + ".")
        proposal = {
            "doc_type": "ACCREC",
            "origin": "request",
            "contact": {"id": (contact or {}).get("ContactID") or "", "name": (contact or {}).get("Name") or customer,
                        "abn": "", "email": email, "is_new": not contact},
            "invoice_number": "",
            "date": date,
            "due_date": due,
